const input = $input.first()?.json ?? {};
const raw = input.output ?? input.text ?? input;

const parseLead = (value) => {
  if (value && typeof value === 'object') return value;

  const text = String(value ?? '').trim();
  if (!text) return {};

  const withoutFence = text
    .replace(/^\x60\x60\x60(?:json)?/i, '')
    .replace(/\x60\x60\x60$/i, '')
    .trim();
  const match = withoutFence.match(/\{[\s\S]*\}/);
  if (!match) return {};

  try {
    const parsed = JSON.parse(match[0]);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    return {};
  }
};

const pick = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};

const normalizeLeadScore = (value) => {
  const score = pick(value)?.toLowerCase();
  return ['hot', 'warm', 'not_interested'].includes(score) ? score : null;
};

const ext = parseLead(raw);
const zaloId = pick($('Zalo Bot Trigger').first()?.json?.message?.chat?.id);

if (!zaloId) {
  throw new Error('Missing Zalo chat ID');
}

return [{
  json: {
    zalo_id: zaloId,
    name: pick(ext.name),
    phone: pick(ext.phone),
    region: pick(ext.region),
    desired_job: pick(ext.desired_job),
    lead_score: normalizeLeadScore(ext.lead_score),
  },
}];

const raw = ($input.first().json?.text ?? $input.first().json?.output ?? '').toString();
let facts = [];

try {
  let text = raw.trim().replace(/^\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60$/i, '').trim();
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start !== -1 && end !== -1 && end > start) text = text.slice(start, end + 1);

  const parsed = JSON.parse(text);
  if (Array.isArray(parsed)) {
    facts = [...new Set(parsed
      .filter((fact) => typeof fact === 'string')
      .map((fact) => fact.trim())
      .filter(Boolean))];
  }
} catch (error) {
  facts = [];
}

return facts.slice(0, 20).map((content) => ({ json: { content } }));
